// Step 1: Validate Common Contract v1.0 Input Envelope
const input = $input.first().json;

if (!input) {
  throw new Error('Empty input envelope');
}

const contractVersion = input.contract_version || '1.0';
const correlationId = input.correlation_id || $execution.id;
const userId = input.user_id;
const sourceChannel = input.source_channel || 'system';
const capturedAt = input.captured_at || new Date().toISOString();
const payload = input.payload || {};

if (!userId) {
  return [{
    json: {
      ok: false,
      status: 'error',
      correlation_id: correlationId,
      error: {
        category: 'validation',
        code: 'MISSING_USER_ID',
        message_safe: 'user_id is required in envelope'
      }
    }
  }];
}

// Step 2: Determine Idempotency Key
let idempotencyKey = payload.idempotency_key;

if (!idempotencyKey) {
  if (sourceChannel === 'telegram') {
    const botAlias = payload.bot_alias || 'primary';
    const updateId = payload.update_id || payload.message_id;
    if (!updateId) {
      throw new Error('Telegram ingestion requires update_id or message_id');
    }
    idempotencyKey = `telegram:${botAlias}:${updateId}`;
  } else if (sourceChannel === 'google_drive') {
    const fileId = payload.file_id;
    const ver = payload.version || payload.modified_time || 'v1';
    if (!fileId) {
      throw new Error('Drive ingestion requires file_id');
    }
    idempotencyKey = `drive:${fileId}:${ver}`;
  } else if (sourceChannel === 'chatgpt_mcp') {
    const reqId = payload.request_id || correlationId;
    idempotencyKey = `mcp:${reqId}`;
  } else if (sourceChannel === 'system') {
    const op = payload.operation || 'generic';
    const period = payload.logical_period || capturedAt.split('T')[0];
    idempotencyKey = `system:${op}:${period}`;
  } else {
    idempotencyKey = `${sourceChannel}:${payload.source_event_key || correlationId}`;
  }
}

return [{
  json: {
    contract_version: contractVersion,
    correlation_id: correlationId,
    user_id: userId,
    source_channel: sourceChannel,
    source_kind: payload.source_kind || 'text',
    source_event_key: payload.source_event_key || null,
    telegram_update_id: payload.update_id || null,
    telegram_message_id: payload.message_id || null,
    telegram_chat_id: payload.chat_id || null,
    telegram_user_id: payload.from_id || null,
    telegram_file_id: payload.file_id && sourceChannel === 'telegram' ? payload.file_id : null,
    drive_file_id: payload.file_id && sourceChannel === 'google_drive' ? payload.file_id : null,
    source_url: payload.source_url || null,
    idempotency_key: idempotencyKey,
    captured_at: capturedAt,
    source_metadata: payload.source_metadata || {}
  }
}];

const raw = $input.first().json;
const prev = $('Validate and Build Ingestion Params').first().json;
const res = typeof raw.result === 'string' ? JSON.parse(raw.result) : (raw.result || raw);

if (res.is_duplicate) {
  return [{
    json: {
      ok: true,
      status: 'duplicate',
      correlation_id: prev.correlation_id,
      data: {
        ingestion_id: res.ingestion_id,
        idempotency_key: prev.idempotency_key,
        is_duplicate: true,
        existing_status: res.existing_status
      },
      warnings: ['Duplicate technical event detected. Ingestion reused.']
    }
  }];
}

return [{
  json: {
    ok: true,
    status: 'completed',
    correlation_id: prev.correlation_id,
    data: {
      ingestion_id: res.ingestion_id,
      idempotency_key: prev.idempotency_key,
      is_duplicate: false
    },
    warnings: []
  }
}];
